#!/usr/bin/env python3

# ----------------------------------------------------------------------
# Usage: python read_csv_csi.py csi_capture_*.csv
# Reads CSV files generated by live_monitor.py --capture-mode complex
# ----------------------------------------------------------------------

import sys
import numpy as np
import pandas as pd
from pathlib import Path


class CSIDataLoader:
    """Load and parse CSI data from CSV files"""
    
    def __init__(self, csv_file):
        self.csv_file = csv_file
        self.df = None
        self.csi_data = None
        self.metadata = None
        
    def load(self):
        """Load CSV and extract CSI data"""
        if not Path(self.csv_file).exists():
            raise FileNotFoundError(f"File '{self.csv_file}' not found!")
        
        print(f"Reading CSV file: {self.csv_file}")
        self.df = pd.read_csv(self.csv_file)
        print(f"CSV shape: {self.df.shape} rows x {self.df.shape[1]} columns")
        
        # Extract data
        self._extract_csi_data()
        self._extract_metadata()
        
        return self.csi_data, self.metadata
    
    def _extract_csi_data(self):
        """Extract complex CSI data from DataFrame"""
        # Identify complex columns
        complex_cols = [col for col in self.df.columns if col not in ['ts', 'seq_num', 'core', 'spatial_stream']]
        n_sc = len(complex_cols) // 2
        print(f"Number of subcarriers detected: {n_sc}")
        
        # Extract complex data
        csi_data = []
        for idx in range(len(self.df)):
            row = self.df.iloc[idx]
            i_vals = [row[f'sc{sc}_re'] for sc in range(n_sc)]
            q_vals = [row[f'sc{sc}_im'] for sc in range(n_sc)]
            complex_csi = np.array(i_vals, dtype=np.float64) + 1j * np.array(q_vals, dtype=np.float64)
            csi_data.append(complex_csi)
        
        self.csi_data = np.array(csi_data)
        self.n_subcarriers = n_sc
        
    def _extract_metadata(self):
        """Extract metadata from DataFrame"""
        timestamps = self.df['ts'].values
        seq_nums = self.df['seq_num'].values
        cores = self.df['core'].values
        spatial_streams = self.df['spatial_stream'].values
        
        self.metadata = {
            'first_ts': timestamps[0],
            'last_ts': timestamps[-1],
            'duration': timestamps[-1] - timestamps[0],
            'n_packets': len(self.df),
            'n_subcarriers': self.n_subcarriers,
            'seq_first': seq_nums[0],
            'seq_last': seq_nums[-1],
            'core': cores[0] if len(np.unique(cores)) == 1 else np.unique(cores).tolist(),
            'spatial_stream': spatial_streams[0] if len(np.unique(spatial_streams)) == 1 else np.unique(spatial_streams).tolist(),
            'rate': len(self.df) / (timestamps[-1] - timestamps[0]),
        }
    
    def save_filtered_csv(self, filtered_data, output_file=None):
        """Save filtered CSI data back to CSV"""
        if output_file is None:
            output_file = self.csv_file.replace('.csv', '_filtered.csv')
        
        df_filtered = self.df.copy()
        
        # Update complex columns with filtered data
        for sc in range(filtered_data.shape[1]):
            df_filtered[f'sc{sc}_re'] = filtered_data[:, sc].real
            df_filtered[f'sc{sc}_im'] = filtered_data[:, sc].imag
        
        df_filtered.to_csv(output_file, index=False)
        print(f"Filtered data saved to {output_file}")
        return output_file


def load_csi_from_csv(csv_file):
    """Convenience function to load CSI data"""
    loader = CSIDataLoader(csv_file)
    return loader.load()


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} csi_capture_*.csv")
        print("\nThis script reads CSV files generated by:")
        print("  live_monitor.py --capture-mode complex")
        sys.exit(1)
    
    try:
        csi_data, metadata = load_csi_from_csv(sys.argv[1])
        print(f"\nSuccessfully loaded {metadata['n_packets']} packets")
        print(f"with {metadata['n_subcarriers']} subcarriers each")
        print(f"Duration: {metadata['duration']:.3f} seconds")
        print(f"Rate: {metadata['rate']:.2f} Hz")
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)